#include <stdio.h>

int main(void) {
    int lcp;
    scanf("%d", &lcp);
    if (lcp < 2500) printf("tot\n");
    else if (lcp <= 4000) printf("can cai thien\n");
    else printf("kem\n");
    return 0;
}
